from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    max_values = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            continue
        max_values[x][y] = value + max(
            max_values[x-1][y] if x > 0 else -float('inf'),
            max_values[x][y-1] if y > 0 else -float('inf')
        )

    path1 = path2 = []
    value = max_values[-1][-1]
    for i in range(N-1, -1, -1):
        if path1 and path1[-1][0] == i and path1[-1][1] == N-1:
            path2.append((i, N-1))
            value = max_values[i][N-1]
            continue
        if max_values[i][N-1] == value:
            path1.append((i, N-1))
            value -= grid_values[i][N-1]

    path2.reverse()

    for i in range(N-1, -1, -1):
        if path2 and path2[-1][1] == i and path2[-1][0] == N-1:
            path2.append((N-1, i))
            value = max_values[N-1][i]
            continue
        if max_values[N-1][i] == value:
            path2.append((N-1, i))
            value -= grid_values[N-1][i]

    path2.reverse()

    return sum(grid_values[x][y] for x, y, _ in path1) + sum(grid_values[x][y] for x, y, _ in path2)
