def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    horizontal_aisles = [0] * N
    vertical_aisles = [0] * M

    for pair in chatting_pairs:
        (Xi, Yi), (Pi, Qi) = pair
        if Xi == Pi:  # Chatting pair is in the same row
            if Yi < Qi:
                vertical_aisles[Xi - 1] += 1
            else:
                vertical_aisles[Xi] += 1
        elif Yi == Qi:  # Chatting pair is in the same column
            if Xi < Pi:
                horizontal_aisles[Yi - 1] += 1
            else:
                horizontal_aisles[Yi] += 1

    horizontal_solutions = []
    for i in range(N - 1):
        if horizontal_aisles[i] > 0:
            count = 0
            for pair in chatting_pairs:
                (Xi, Yi), (Pi, Qi) = pair
                if Yi == i + 1 or Yi == i + 2:
                    if Xi < Pi:
                        count += 1
                    else:
                        count -= 1
            horizontal_solutions.append((count, i + 1))

    vertical_solutions = []
    for i in range(M - 1):
        if vertical_aisles[i] > 0:
            count = 0
            for pair in chatting_pairs:
                (Xi, Yi), (Pi, Qi) = pair
                if Xi == i + 1 or Xi == i + 2:
                    if Yi < Qi:
                        count += 1
                    else:
                        count -= 1
            vertical_solutions.append((count, i + 1))

    horizontal_aisles_solution = max(horizontal_solutions, key=lambda x: x[0])[1] if horizontal_solutions else 0
    vertical_aisles_solution = max(vertical_solutions, key=lambda x: x[0])[1] if vertical_solutions else 0

    return str(horizontal_aisles_solution), f"{vertical_aisles_solution} {horizontal_aisles_solution}" if K == 0 and L == 0 else str(vertical_aisles_solution)

