def max_energy(beads):
    n = len(beads)
    beads.extend(beads)  # Extend the list to handle the circular nature
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i] * beads[k + 1] * beads[j + 1])

    return dp[0][n - 1]
